def server(request):
    if request['method'] == 'GET' and request['path'] == '/hello':
        return {'status': 200, 'body': 'Hello!'}
    return {'status': 404, 'body': 'Not Found'}

def client(path):
    response = server({'method': 'GET', 'path': path})
    print(path, '->', response['status'], response['body'])

client('/hello')
client('/missing')

