import json

class FakeResponse:
    def __init__(self, status_code, text):
        self.status_code = status_code
        self.text = text

    def json(self):
        return json.loads(self.text)

response = FakeResponse(200, '[{"name": "Finland"}, {"name": "Sweden"}]')
if response.status_code == 200:
    print([c['name'] for c in response.json()])
